package com.example.agent; import android.app.Activity; import android.os.Bundle; import android.graphics.Color; import android.view.Gravity; import android.widget.LinearLayout; import android.widget.ScrollView; import android.widget.TextView; import android.widget.EditText; import android.widget.Button; public class MainActivity extends Activity { LinearLayout messages; EditText input; @Override protected void onCreate(Bundle savedInstanceState) { super.onCreate(savedInstanceState); LinearLayout root = new LinearLayout(this); root.setOrientation(LinearLayout.VERTICAL); root.setPadding(24, 24, 24, 16); root.setBackgroundColor(Color.rgb(245, 247, 250)); TextView title = new TextView(this); title.setText("الوكيل الذكي AgentApp"); title.setTextSize(23); title.setTextColor(Color.rgb(20, 70, 130)); title.setGravity(Gravity.CENTER); title.setPadding(8, 16, 8, 20); ScrollView scroll = new ScrollView(this); messages = new LinearLayout(this); messages.setOrientation(LinearLayout.VERTICAL); scroll.addView(messages); addMessage("الوكيل الذكي جاهز لاستقبال أوامرك."); LinearLayout bottom = new LinearLayout(this); bottom.setOrientation(LinearLayout.HORIZONTAL); bottom.setGravity(Gravity.CENTER_VERTICAL); input = new EditText(this); input.setHint("اكتب ما تريد..."); input.setTextSize(16); input.setSingleLine(false); Button send = new Button(this); send.setText("إرسال"); bottom.addView(input, new LinearLayout.LayoutParams( 0, LinearLayout.LayoutParams.WRAP_CONTENT, 1)); bottom.addView(send, new LinearLayout.LayoutParams( LinearLayout.LayoutParams.WRAP_CONTENT, LinearLayout.LayoutParams.WRAP_CONTENT)); root.addView(title); root.addView(scroll, new LinearLayout.LayoutParams( LinearLayout.LayoutParams.MATCH_PARENT, 0, 1)); root.addView(bottom); setContentView(root); send.setOnClickListener(v -> { String command = input.getText().toString().trim(); if (command.isEmpty()) { return; } addMessage("أنت: " + command); input.setText(""); addMessage("الوكيل: استلمت طلبك. لم يتم ربط الذكاء الاصطناعي بعد."); }); } private void addMessage(String message) { TextView text = new TextView(this); text.setText(message); text.setTextSize(17); text.setTextColor(Color.DKGRAY); text.setPadding(16, 16, 16, 16); LinearLayout.LayoutParams params = new LinearLayout.LayoutParams( LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT); params.setMargins(0, 0, 0, 12); messages.addView(text, params); } } 
